function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 200000) return 's needs 1 to 200000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is from 1 to s.length.';
  return null;
}

