function countKSubsequencesWithMaxBeauty(s, k) {
  const MOD = 1_000_000_007n;
  const freq = new Map();
  for (const ch of s) {
    freq.set(ch, (freq.get(ch) ?? 0) + 1);
  }
  if (k > freq.size) {
    return 0;
  }

  const groups = new Map();
  for (const f of freq.values()) {
    groups.set(f, (groups.get(f) ?? 0) + 1);
  }
  const levels = [...groups.keys()].sort((a, b) => b - a);

  let result = 1n;
  let remaining = k;
  for (const f of levels) {
    if (remaining === 0) {
      break;
    }
    const letters = groups.get(f);
    const take = Math.min(remaining, letters);
    let ways = 1;
    for (let i = 1; i <= take; i++) {
      ways = ways * (letters - take + i) / i;
    }
    result = result * BigInt(ways) % MOD;
    for (let i = 0; i < take; i++) {
      result = result * BigInt(f) % MOD;
    }
    remaining -= take;
  }
  return Number(result);
}

