function countKSubsequencesWithMaxBeauty(s, k) {
  // Enumerate every set of k positions with distinct letters directly.
  const f = new Map();
  for (const ch of s) f.set(ch, (f.get(ch) || 0) + 1);
  let best = -1, count = 0;
  const used = new Set();
  const walk = (start, picked, beauty) => {
    if (picked === k) {
      if (beauty > best) { best = beauty; count = 0; }
      if (beauty === best) count++;
      return;
    }
    for (let i = start; i <= s.length - (k - picked); i++) {
      if (used.has(s[i])) continue;
      used.add(s[i]);
      walk(i + 1, picked + 1, beauty + f.get(s[i]));
      used.delete(s[i]);
    }
  };
  walk(0, 0, 0);
  return count % 1000000007;
}

