function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const alphabet = 1 + Math.floor(rand() * 5);
    let s = '';
    for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alphabet)];
    return [s, 1 + Math.floor(rand() * n)];
  }
  // Frequencies come from a narrow band so that several letters tie.
  const alphabet = 1 + Math.floor(rand() * 26);
  const base = 50 + Math.floor(rand() * 300);
  const spread = 1 + Math.floor(rand() * 3);
  const chars = [];
  for (let c = 0; c < alphabet; c++) {
    const count = base + Math.floor(rand() * spread);
    for (let i = 0; i < count; i++) chars.push(letters[c]);
  }
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  const k = 1 + Math.floor(rand() * (alphabet + 2));
  return [chars.join(''), k];
}
